            | "linux/sched.h"
            | "linux/seccomp.h"
            | "linux/sockios.h"
            | "linux/types.h"
            | "linux/unistd.h"
            | "linux/version.h"
            // Standard macOS / Darwin / Win32 headers
            | "mach/clock.h"
            | "mach/mach.h"
