                            || pathlib_mod_names.contains(m)
                            || io_mod_names.contains(m)
                            || subprocess_mod_names.contains(m)
                            || shutil_mod_names.contains(m)
                            || asyncio_mod_names.contains(m)
                            || importlib_mod_names.contains(m)
